(510,5,32,'heading',4,'9.2 Primary and Secondary Metabolites',NULL,NULL,NULL,NULL),
(511,5,33,'paragraph',NULL,'The most exciting aspect of chemistry deals with isolating thousands of compounds, small and big, from living organisms, determining their structure and if possible synthesising them.','[{"s": "The most exciting aspect of chemistry deals with isolating thousands of compounds, small and big, from living organisms, determining their structure and if possible synthesising them.", "t": "text"}]',NULL,NULL,NULL),
(512,5,34,'paragraph',NULL,'Table 9.3 Some Secondary Metabolites','[{"s": "Table 9.3", "t": "hl"}, {"s": "Some Secondary Metabolites", "t": "hl"}]','marked','["91337", "91338", "91343", "91346"]',NULL),
