(905,9,28,'heading',4,'17.2.1 Respiratory Volumes and Capacities',NULL,NULL,NULL,NULL),
(911,9,34,'paragraph',NULL,'Inspiratory Capacity (IC): Total volume of air a person can inspire after a normal expiration. This includes tidal volume and inspiratory reserve volume ( TV+IRV).','[{"s": "Inspiratory Capacity (IC): Total volume of air a person can inspire after a normal expiration. This includes tidal volume and inspiratory reserve volume ( TV+IRV).", "t": "text"}]',NULL,NULL,NULL),
(913,9,36,'paragraph',NULL,'Functional Residual Capacity (FRC): Volume of air that will remain in the lungs after a normal expiration. This includes ERV+RV.','[{"s": "Functional Residual Capacity (FRC): Volume of air that will remain in the lungs after a normal expiration. This includes ERV+RV.", "t": "text"}]',NULL,NULL,NULL),
