(3488,30,81,'paragraph',NULL,'Figure 2.11 (a) Pollination by water in Vallisneria;','[{"s": "Figure 2.11", "t": "text"}, {"s": "(a) Pollination by water in Vallisneria;", "t": "text"}]',NULL,NULL,NULL),
(3404,29,85,'paragraph',NULL,'Plants unlike animals have no special systems for breathing or gaseous exchange. Stomata and lenticels allow gaseous exchange by diffusion. Almost all living cells in a plant have their surfaces exposed to air.','[{"s": "Plants unlike animals have no special systems for breathing or gaseous exchange. Stomata and lenticels allow gaseous exchange by diffusion. Almost all living cells in a plant have their surfaces exposed to air.", "t": "text"}]',NULL,NULL,NULL),
