(3991,34,55,'paragraph',NULL,'(iv) Alcohols_Phenols_and_Ethers-image148.png','[{"s": "(iv)", "t": "text"}, {"s": "Alcohols_Phenols_and_Ethers-image148.png", "t": "img", "alt": "bond-233"}]',NULL,NULL,NULL),
(3992,34,56,'paragraph',NULL,'Solution','[{"s": "Solution", "t": "text"}]',NULL,NULL,NULL),
(3993,34,57,'paragraph',NULL,'(i) 4-Chloro-2,3-dimethylpentan-1-ol','[{"s": "(i) 4-Chloro-2,3-dimethylpentan-1-ol", "t": "text"}]',NULL,NULL,NULL),
(3994,34,58,'paragraph',NULL,'(ii) 2-Ethoxypropane','[{"s": "(ii) 2-Ethoxypropane", "t": "text"}]',NULL,NULL,NULL),
(3995,34,59,'paragraph',NULL,'(iii) 2,6-Dimethylphenol','[{"s": "(iii) 2,6-Dimethylphenol", "t": "text"}]',NULL,NULL,NULL),
(3996,34,60,'paragraph',NULL,'(iv) 1-Ethoxy-2-nitrocyclohexane','[{"s": "(iv) 1-Ethoxy-2-nitrocyclohexane", "t": "text"}]',NULL,NULL,NULL),
(3997,34,61,'paragraph',NULL,'According to IUPAC system of nomenclature, ethers are regarded as hydrocarbon derivatives in which a hydrogen atom is replaced by an – OR or – OAr group, where R and Ar represent alkyl and aryl groups, respectively. The larger (R) group is chosen as the parent hydrocarbon. The names of a few ethers are given as examples in Table 11.2.','[{"s": "According to IUPAC system of nomenclature, ethers are regarded as hydrocarbon derivatives in which a hydrogen atom is replaced by an –", "t": "text"}, {"s": "OR", "t": "text"}, {"s": "or –", "t": "text"}, {"s": "OAr", "t": "text"}, {"s": "group, where R and Ar represent alkyl and aryl groups, respectively. The larger (R) group is chosen as the parent hydrocarbon. The names of a few ethers are given as examples in Table 11.2.", "t": "text"}]',NULL,NULL,NULL),
(3998,34,62,'paragraph',NULL,'Intext Question','[{"s": "Intext Question", "t": "text"}]',NULL,NULL,NULL),
(3999,34,63,'paragraph',NULL,'11.3 Name the following compounds according to IUPAC system.','[{"s": "11.3", "t": "text"}, {"s": "Name the following compounds according to IUPAC system.", "t": "text"}]',NULL,NULL,NULL),
