(4214,34,278,'paragraph',NULL,'3. Reimer-Tiemann reaction','[{"s": "3. Reimer-Tiemann reaction", "t": "text"}]',NULL,NULL,NULL),
(4215,34,279,'paragraph',NULL,'On treating phenol with chloroform in the presence of sodium hydroxide, a –CHO group is introduced at ortho position of benzene ring. 2 This reaction is known as Reimer - Tiemann reaction.','[{"s": "On treating phenol with chloroform in the presence of sodium hydroxide, a –CHO group is introduced at ortho position of benzene ring.", "t": "hl"}, {"s": "2", "t": "hl"}, {"s": "This reaction is known as Reimer - Tiemann reaction.", "t": "text"}]','marked','["250980", "250981"]',NULL),
(4216,34,280,'paragraph',NULL,'The intermediate substituted benzal chloride is hydrolysed in the presence of alkali to produce salicylaldehyde. 2','[{"s": "The intermediate substituted benzal chloride is hydrolysed in the presence of alkali to produce salicylaldehyde.", "t": "hl"}, {"s": "2", "t": "hl"}]','marked','["250895", "250979"]',NULL),
