(6079,37,211,'paragraph',NULL,'ln[R] = -kt + ln[R] 0 (4.9)','[{"s": "ln[R] = -kt + ln[R]", "t": "text"}, {"s": "0", "t": "text"}, {"s": "(4.9)", "t": "text"}]',NULL,NULL,NULL),
