(6743,37,875,'paragraph',NULL,'Q.61 Assertion (A) Rate constant determined from the Arrhenius equation is fairly accurate for simple as well as complex molecules.','[{"s": "Q.61 Assertion (A) Rate constant determined from the Arrhenius equation is fairly accurate for simple as well as complex molecules.", "t": "text"}]',NULL,NULL,NULL),
(6744,37,876,'paragraph',NULL,'Reason (R) Reactant molecules undergo chemical change irrespective of their orientation during a collision.','[{"s": "Reason (R) Reactant molecules undergo chemical change irrespective of their orientation during a collision.", "t": "text"}]',NULL,NULL,NULL),
(6745,37,877,'paragraph',NULL,'Q.62 All energetically effective collisions do not result in a chemical change. Explain with the help of an example.','[{"s": "Q.62 All energetically effective collisions do not result in a chemical change. Explain with the help of an example.", "t": "text"}]',NULL,NULL,NULL),
