(6747,37,879,'paragraph',NULL,'Q.64 Describe how does the enthalpy of reaction remains unchanged when a catalyst is used in the reaction?','[{"s": "Q.64 Describe how does the enthalpy of reaction remains unchanged when a catalyst is used in the reaction?", "t": "text"}]',NULL,NULL,NULL),
(6748,37,880,'paragraph',NULL,'Q.65 Explain the difference between the instantaneous rate of a reaction and the average rate of a reaction.','[{"s": "Q.65 Explain the difference between the instantaneous rate of a reaction and the average rate of a reaction.", "t": "text"}]',NULL,NULL,NULL),
