(6753,38,3,'paragraph',NULL,'After studying this Unit, you will be able to','[{"s": "After studying this Unit, you will be able to", "t": "text"}]',NULL,NULL,NULL),
(6754,38,4,'paragraph',NULL,'• understand KÖssel-Lewis approach to chemical bonding;','[{"s": "•", "t": "text"}, {"s": "understand KÖssel-Lewis approach to chemical bonding;", "t": "text"}]',NULL,NULL,NULL),
(6755,38,5,'paragraph',NULL,'• explain the octet rule and its limitations, draw Lewis structures of simple molecules;','[{"s": "•", "t": "text"}, {"s": "explain the octet rule and its limitations, draw Lewis structures of simple molecules;", "t": "text"}]',NULL,NULL,NULL),
(6756,38,6,'paragraph',NULL,'• explain the formation of different types of bonds;','[{"s": "•", "t": "text"}, {"s": "explain the formation of different types of bonds;", "t": "text"}]',NULL,NULL,NULL),
(6757,38,7,'paragraph',NULL,'• describe the VSEPR theory and predict the geometry of simple molecules;','[{"s": "•", "t": "text"}, {"s": "describe the VSEPR theory and predict the geometry of simple molecules;", "t": "text"}]',NULL,NULL,NULL),
(6758,38,8,'paragraph',NULL,'• explain the valence bond approach for the formation of covalent bonds;','[{"s": "•", "t": "text"}, {"s": "explain the valence bond approach for the formation of covalent bonds;", "t": "text"}]',NULL,NULL,NULL),
(6759,38,9,'paragraph',NULL,'• predict the directional properties of covalent bonds;','[{"s": "•", "t": "text"}, {"s": "predict the directional properties of covalent bonds;", "t": "text"}]',NULL,NULL,NULL),
(6760,38,10,'paragraph',NULL,'• explain the different types of hybridisation involving s , p and d orbitals and draw shapes of simple covalent molecules;','[{"s": "•", "t": "text"}, {"s": "explain the different types of hybridisation involving", "t": "text"}, {"s": "s", "t": "text"}, {"s": ",", "t": "text"}, {"s": "p", "t": "text"}, {"s": "and", "t": "text"}, {"s": "d", "t": "text"}, {"s": "orbitals and draw shapes of simple covalent molecules;", "t": "text"}]',NULL,NULL,NULL),
(6761,38,11,'paragraph',NULL,'• describe the molecular orbital theory of homonuclear diatomic molecules;','[{"s": "•", "t": "text"}, {"s": "describe the molecular orbital theory of homonuclear diatomic molecules;", "t": "text"}]',NULL,NULL,NULL),
