(7873,40,9,'paragraph',NULL,'1 mol CoCl 3 .6NH 3 (Yellow) gave 3 mol AgCl 2','[{"s": "1 mol CoCl", "t": "hl"}, {"s": "3", "t": "hl"}, {"s": ".6NH", "t": "hl"}, {"s": "3", "t": "hl"}, {"s": "(Yellow) gave 3 mol AgCl", "t": "hl"}, {"s": "2", "t": "hl"}]','marked','["231308", "231318"]',NULL),
(7874,40,10,'paragraph',NULL,'1 mol CoCl 3 .5NH 3 (Purple) gave 2 mol AgCl','[{"s": "1 mol CoCl", "t": "text"}, {"s": "3", "t": "text"}, {"s": ".5NH", "t": "text"}, {"s": "3", "t": "text"}, {"s": "(Purple) gave 2 mol AgCl", "t": "text"}]',NULL,NULL,NULL),
(7875,40,11,'paragraph',NULL,'1 mol CoCl 3 .4NH 3 (Green) gave 1 mol AgCl','[{"s": "1 mol CoCl", "t": "text"}, {"s": "3", "t": "text"}, {"s": ".4NH", "t": "text"}, {"s": "3", "t": "text"}, {"s": "(Green) gave 1 mol AgCl", "t": "text"}]',NULL,NULL,NULL),
