(8110,40,246,'paragraph',NULL,'[Ni(H 2 O) 4 (en)] 2+ (aq) + en (aq) = [Ni(H 2 O) 2 (en) 2 ] 2+ (aq) + 2H 2 O','[{"s": "[Ni(H", "t": "text"}, {"s": "2", "t": "text"}, {"s": "O)", "t": "text"}, {"s": "4", "t": "text"}, {"s": "(en)]", "t": "text"}, {"s": "2+", "t": "text"}, {"s": "(aq) + en (aq) = [Ni(H", "t": "text"}, {"s": "2", "t": "text"}, {"s": "O)", "t": "text"}, {"s": "2", "t": "text"}, {"s": "(en)", "t": "text"}, {"s": "2", "t": "text"}, {"s": "]", "t": "text"}, {"s": "2+", "t": "text"}, {"s": "(aq) + 2H", "t": "text"}, {"s": "2", "t": "text"}, {"s": "O", "t": "text"}]',NULL,NULL,NULL),
(8111,40,247,'paragraph',NULL,'blue/purple','[{"s": "blue/purple", "t": "text"}]',NULL,NULL,NULL),
(8112,40,248,'paragraph',NULL,'[Ni(H 2 O) 2 (en) 2 ] 2+ (aq) + en (aq) = [Ni(en) 3 ] 2+ (aq) + 2H 2 O','[{"s": "[Ni(H", "t": "text"}, {"s": "2", "t": "text"}, {"s": "O)", "t": "text"}, {"s": "2", "t": "text"}, {"s": "(en)", "t": "text"}, {"s": "2", "t": "text"}, {"s": "]", "t": "text"}, {"s": "2+", "t": "text"}, {"s": "(aq) + en (aq) = [Ni(en)", "t": "text"}, {"s": "3", "t": "text"}, {"s": "]", "t": "text"}, {"s": "2+", "t": "text"}, {"s": "(aq) + 2H", "t": "text"}, {"s": "2", "t": "text"}, {"s": "O", "t": "text"}]',NULL,NULL,NULL),
