(9264,42,42,'paragraph',NULL,'As E Ɵ L for standard hydrogen electrode is zero.','[{"s": "As E", "t": "text"}, {"s": "Ɵ", "t": "text"}, {"s": "L", "t": "text"}, {"s": "for standard hydrogen electrode is zero.", "t": "text"}]',NULL,NULL,NULL),
(9265,42,43,'paragraph',NULL,'E Ɵ = E Ɵ R – 0 = E Ɵ R','[{"s": "E", "t": "text"}, {"s": "Ɵ", "t": "text"}, {"s": "= E", "t": "text"}, {"s": "Ɵ", "t": "text"}, {"s": "R", "t": "text"}, {"s": "– 0 = E", "t": "text"}, {"s": "Ɵ", "t": "text"}, {"s": "R", "t": "text"}]',NULL,NULL,NULL),
