(9278,42,56,'paragraph',NULL,'The overall reaction of the cell is the sum of above two reactions and we obtain the equation:','[{"s": "The overall reaction of the cell is the sum of above two reactions and we obtain the equation:", "t": "hl"}]','marked','["171164"]',NULL),
(9279,42,57,'paragraph',NULL,'Zn(s) + Cu 2+ (aq) → Zn 2+ (aq) + Cu(s)','[{"s": "Zn(s) + Cu", "t": "text"}, {"s": "2+", "t": "text"}, {"s": "(aq) → Zn", "t": "text"}, {"s": "2+", "t": "text"}, {"s": "(aq) + Cu(s)", "t": "text"}]',NULL,NULL,NULL),
