(9282,42,60,'paragraph',NULL,'Sometimes metals like platinum or gold are used as inert electrodes. They do not participate in the reaction but provide their surface for oxidation or reduction reactions and for the conduction of electrons. For example, Pt is used in the following half-cells:','[{"s": "Sometimes metals like platinum or gold are used as inert electrodes. They do not participate in the reaction but provide their surface for oxidation or reduction reactions and for the conduction of electrons. For example, Pt is used in the following half-cells:", "t": "text"}]',NULL,NULL,NULL),
(9283,42,61,'paragraph',NULL,'Hydrogen electrode: Pt(s) | H 2 (g) | H + (aq)','[{"s": "Hydrogen electrode: Pt(s) | H", "t": "text"}, {"s": "2", "t": "text"}, {"s": "(g) | H", "t": "text"}, {"s": "+", "t": "text"}, {"s": "(aq)", "t": "text"}]',NULL,NULL,NULL),
(9284,42,62,'paragraph',NULL,'With half-cell reaction: H + (aq)+ e – → ½ H 2 (g)','[{"s": "With half-cell reaction: H", "t": "text"}, {"s": "+", "t": "text"}, {"s": "(aq)+ e", "t": "text"}, {"s": "–", "t": "text"}, {"s": "→ ½ H", "t": "text"}, {"s": "2", "t": "text"}, {"s": "(g)", "t": "text"}]',NULL,NULL,NULL),
(9285,42,63,'paragraph',NULL,'Bromine electrode: Pt(s) | Br 2 (aq) | Br – (aq)','[{"s": "Bromine electrode: Pt(s) | Br", "t": "text"}, {"s": "2", "t": "text"}, {"s": "(aq) | Br", "t": "text"}, {"s": "–", "t": "text"}, {"s": "(aq)", "t": "text"}]',NULL,NULL,NULL),
