(9560,42,338,'paragraph',NULL,'One mole of the electron is required for the reduction of one mole of silver ions.','[{"s": "One mole of the electron is required for the reduction of one mole of silver ions.", "t": "text"}]',NULL,NULL,NULL),
(9561,42,339,'paragraph',NULL,'We know that charge on one electron is equal to 1.6021× 10 –19 C.','[{"s": "We know that charge on one electron is equal to 1.6021× 10", "t": "text"}, {"s": "–19", "t": "text"}, {"s": "C.", "t": "text"}]',NULL,NULL,NULL),
