(10055,43,41,'paragraph',NULL,'rate of evaporation= rate of condensation','[{"s": "rate of evaporation= rate of condensation", "t": "text"}]',NULL,NULL,NULL),
(10056,43,42,'paragraph',NULL,'H 2 O(l) Equilibrium-image1.png H 2 O (vap)','[{"s": "H", "t": "text"}, {"s": "2", "t": "text"}, {"s": "O(l)", "t": "text"}, {"s": "Equilibrium-image1.png", "t": "img", "alt": ""}, {"s": "H", "t": "text"}, {"s": "2", "t": "text"}, {"s": "O (vap)", "t": "text"}]',NULL,NULL,NULL),
