(10187,43,173,'heading',4,'7.4.1 Equilibrium Constant in Gaseous Systems',NULL,NULL,NULL,NULL),
(10188,43,174,'paragraph',NULL,'So far we have expressed equilibrium constant of the reactions in terms of molar concentration of the reactants and products, and used symbol, K c for it. For reactions involving gases, however, it is usually more convenient to express the equilibrium constant in terms of partial pressure.','[{"s": "So far we have expressed equilibrium constant of the reactions in terms of molar concentration of the reactants and products, and used symbol,", "t": "text"}, {"s": "K", "t": "text"}, {"s": "c", "t": "text"}, {"s": "for it. For reactions involving gases, however, it is usually more convenient to express the equilibrium constant in terms of partial pressure.", "t": "text"}]',NULL,NULL,NULL),
(10189,43,175,'paragraph',NULL,'The ideal gas equation is written as,','[{"s": "The ideal gas equation is written as,", "t": "text"}]',NULL,NULL,NULL),
(10190,43,176,'paragraph',NULL,'pV = n R T','[{"s": "pV", "t": "text"}, {"s": "=", "t": "text"}, {"s": "n", "t": "text"}, {"s": "R", "t": "text"}, {"s": "T", "t": "text"}]',NULL,NULL,NULL),
(10191,43,177,'image',NULL,'Screenshot from 2019-06-05 19-13-10',NULL,NULL,NULL,'/ncert/chemistry/images/Equilibrium-image26.png'),
(10192,43,178,'paragraph',NULL,'Here, p is the pressure in Pa, n is the number of moles of the gas, V is the volume in m3 and T is the temperature in Kelvin','[{"s": "Here,", "t": "text"}, {"s": "p", "t": "text"}, {"s": "is the pressure in Pa,", "t": "text"}, {"s": "n", "t": "text"}, {"s": "is the number of moles of the gas,", "t": "text"}, {"s": "V", "t": "text"}, {"s": "is the volume in", "t": "text"}, {"s": "m3", "t": "text"}, {"s": "and", "t": "text"}, {"s": "T", "t": "text"}, {"s": "is the temperature in Kelvin", "t": "text"}]',NULL,NULL,NULL),
(10193,43,179,'paragraph',NULL,'Therefore,','[{"s": "Therefore,", "t": "text"}]',NULL,NULL,NULL),
(10194,43,180,'paragraph',NULL,'n / V is concentration expressed in mol/m 3','[{"s": "n", "t": "text"}, {"s": "/", "t": "text"}, {"s": "V", "t": "text"}, {"s": "is concentration expressed in mol/m", "t": "text"}, {"s": "3", "t": "text"}]',NULL,NULL,NULL),
(10195,43,181,'paragraph',NULL,'If concentration c, is in mol/L or mol/ d m 3 , and p is in bar then','[{"s": "If concentration c, is in mol/L or mol/", "t": "text"}, {"s": "d", "t": "text"}, {"s": "m", "t": "text"}, {"s": "3", "t": "text"}, {"s": ", and", "t": "text"}, {"s": "p", "t": "text"}, {"s": "is in bar then", "t": "text"}]',NULL,NULL,NULL),
(10196,43,182,'paragraph',NULL,'p = c R T ,','[{"s": "p", "t": "text"}, {"s": "=", "t": "text"}, {"s": "c", "t": "text"}, {"s": "R", "t": "text"}, {"s": "T", "t": "text"}, {"s": ",", "t": "text"}]',NULL,NULL,NULL),
