(10198,43,184,'paragraph',NULL,'Here, R= 0.0831 bar litre/mol K','[{"s": "Here, R= 0.0831 bar litre/mol K", "t": "text"}]',NULL,NULL,NULL),
(10199,43,185,'paragraph',NULL,'At constant temperature, the pressure of the gas is proportional to its concentration i.e.,','[{"s": "At constant temperature, the pressure of the gas is proportional to its concentration i.e.,", "t": "text"}]',NULL,NULL,NULL),
