(10265,43,251,'paragraph',NULL,'In this example, there is a gas phase and a liquid phase. In the same way, equilibrium between a solid and its saturated solution,','[{"s": "In this example, there is a gas phase and a liquid phase. In the same way, equilibrium between a solid and its saturated solution,", "t": "text"}]',NULL,NULL,NULL),
(10266,43,252,'paragraph',NULL,'Ca(OH) 2 (s) + (aq) Equilibrium-image1.png Ca 2+ (aq) + 2OH – (aq)','[{"s": "Ca(OH)", "t": "text"}, {"s": "2", "t": "text"}, {"s": "(s) + (aq)", "t": "text"}, {"s": "Equilibrium-image1.png", "t": "img", "alt": ""}, {"s": "Ca", "t": "text"}, {"s": "2+", "t": "text"}, {"s": "(aq) + 2OH", "t": "text"}, {"s": "–", "t": "text"}, {"s": "(aq)", "t": "text"}]',NULL,NULL,NULL),
