(10387,43,373,'paragraph',NULL,'The total pressure at equilbrium was found to be 9.15 bar. Calculate K c , K p and partial pressure at equilibrium.','[{"s": "The total pressure at equilbrium was found to be 9.15 bar. Calculate", "t": "text"}, {"s": "K", "t": "text"}, {"s": "c", "t": "text"}, {"s": ",", "t": "text"}, {"s": "K", "t": "text"}, {"s": "p", "t": "text"}, {"s": "and partial pressure at equilibrium.", "t": "text"}]',NULL,NULL,NULL),
(10388,43,374,'paragraph',NULL,'Solution','[{"s": "Solution", "t": "text"}]',NULL,NULL,NULL),
