(10397,43,383,'paragraph',NULL,'p × 1L = 0.15 mol × 0.083 bar L mol –1 K –1 × 400 K','[{"s": "p", "t": "text"}, {"s": "× 1L = 0.15 mol × 0.083 bar L mol", "t": "text"}, {"s": "–1", "t": "text"}, {"s": "K", "t": "text"}, {"s": "–1", "t": "text"}, {"s": "× 400 K", "t": "text"}]',NULL,NULL,NULL),
(10398,43,384,'paragraph',NULL,'p = 4.98 bar','[{"s": "p", "t": "text"}, {"s": "= 4.98 bar", "t": "text"}]',NULL,NULL,NULL),
