(10400,43,386,'paragraph',NULL,'Initial pressure: 4.98 bar 0','[{"s": "Initial pressure: 4.98 bar 0", "t": "text"}]',NULL,NULL,NULL),
(10401,43,387,'paragraph',NULL,'At equilibrium: (4.98 – x) bar 2x bar Hence,','[{"s": "At equilibrium: (4.98 – x) bar 2x bar Hence,", "t": "text"}]',NULL,NULL,NULL),
(10402,43,388,'paragraph',NULL,'p total at equilibrium = p N2O4 + p NO2','[{"s": "p", "t": "text"}, {"s": "total", "t": "text"}, {"s": "at equilibrium =", "t": "text"}, {"s": "p", "t": "text"}, {"s": "N2O4", "t": "text"}, {"s": "+", "t": "text"}, {"s": "p", "t": "text"}, {"s": "NO2", "t": "text"}]',NULL,NULL,NULL),
(10403,43,389,'paragraph',NULL,'9.15 = (4.98 – x) + 2x','[{"s": "9.15 = (4.98 – x) + 2x", "t": "text"}]',NULL,NULL,NULL),
(10404,43,390,'paragraph',NULL,'9.15 = 4.98 + x','[{"s": "9.15 = 4.98 + x", "t": "text"}]',NULL,NULL,NULL),
(10405,43,391,'paragraph',NULL,'x = 9.15 – 4.98 = 4.17 bar','[{"s": "x = 9.15 – 4.98 = 4.17 bar", "t": "text"}]',NULL,NULL,NULL),
(10406,43,392,'paragraph',NULL,'Partial pressures at equilibrium are,','[{"s": "Partial pressures at equilibrium are,", "t": "text"}]',NULL,NULL,NULL),
(10407,43,393,'paragraph',NULL,'p N2O4 = 4.98 – 4.17 = 0.81bar','[{"s": "p", "t": "text"}, {"s": "N2O4", "t": "text"}, {"s": "= 4.98 – 4.17 = 0.81bar", "t": "text"}]',NULL,NULL,NULL),
(10408,43,394,'paragraph',NULL,'p NO2 = 2x = 2 × 4.17 = 8.34 bar','[{"s": "p", "t": "text"}, {"s": "NO2", "t": "text"}, {"s": "= 2x = 2 × 4.17 = 8.34 bar", "t": "text"}]',NULL,NULL,NULL),
(10409,43,395,'paragraph',NULL,'Equilibrium-image25.png 2 /0.81 = 85.87','[{"s": "Equilibrium-image25.png", "t": "img", "alt": "Screenshot from 2019-06-05 19-35-07"}, {"s": "", "t": "br"}, {"s": "2", "t": "text"}, {"s": "/0.81 = 85.87", "t": "text"}]',NULL,NULL,NULL),
(10410,43,396,'paragraph',NULL,'K p = K c (R T )∆ n','[{"s": "K", "t": "text"}, {"s": "p", "t": "text"}, {"s": "=", "t": "text"}, {"s": "K", "t": "text"}, {"s": "c", "t": "text"}, {"s": "(R", "t": "text"}, {"s": "T", "t": "text"}, {"s": ")∆", "t": "text"}, {"s": "n", "t": "text"}]',NULL,NULL,NULL),
(10411,43,397,'paragraph',NULL,'85.87 = K c (0.083 × 400) 1','[{"s": "85.87 =", "t": "text"}, {"s": "K", "t": "text"}, {"s": "c", "t": "text"}, {"s": "(0.083 × 400)", "t": "text"}, {"s": "1", "t": "text"}]',NULL,NULL,NULL),
(10412,43,398,'paragraph',NULL,'K c = 2.586 = 2.6','[{"s": "K", "t": "text"}, {"s": "c", "t": "text"}, {"s": "= 2.586 = 2.6", "t": "text"}]',NULL,NULL,NULL),
(10413,43,399,'paragraph',NULL,'Problem 7.9','[{"s": "Problem 7.9", "t": "text"}]',NULL,NULL,NULL),
(10414,43,400,'paragraph',NULL,'3.00 mol of PCl 5 kept in 1L closed reaction vessel was allowed to attain equilibrium at 380K. Calculate composition of the mixture at equilibrium. K c = 1.80','[{"s": "3.00 mol of PCl", "t": "text"}, {"s": "5", "t": "text"}, {"s": "kept in 1L closed reaction vessel was allowed to attain equilibrium at 380K. Calculate composition of the mixture at equilibrium.", "t": "text"}, {"s": "K", "t": "text"}, {"s": "c", "t": "text"}, {"s": "= 1.80", "t": "text"}]',NULL,NULL,NULL),
(10415,43,401,'paragraph',NULL,'Solution','[{"s": "Solution", "t": "text"}]',NULL,NULL,NULL),
(10416,43,402,'paragraph',NULL,'PCl 5 Equilibrium-image1.png PCl 3 + Cl 2','[{"s": "PCl", "t": "text"}, {"s": "5", "t": "text"}, {"s": "Equilibrium-image1.png", "t": "img", "alt": ""}, {"s": "PCl", "t": "text"}, {"s": "3", "t": "text"}, {"s": "+ Cl", "t": "text"}, {"s": "2", "t": "text"}]',NULL,NULL,NULL),
(10417,43,403,'paragraph',NULL,'Initial','[{"s": "Initial", "t": "text"}]',NULL,NULL,NULL),
(10418,43,404,'paragraph',NULL,'concentration: 3.0 0 0','[{"s": "concentration: 3.0 0 0", "t": "text"}]',NULL,NULL,NULL),
(10419,43,405,'paragraph',NULL,'Let x mol per litre of PCl 5 be dissociated,','[{"s": "Let x mol per litre of PCl", "t": "text"}, {"s": "5", "t": "text"}, {"s": "be dissociated,", "t": "text"}]',NULL,NULL,NULL),
(10420,43,406,'paragraph',NULL,'At equilibrium:','[{"s": "At equilibrium:", "t": "text"}]',NULL,NULL,NULL),
(10421,43,407,'paragraph',NULL,'(3-x) x x','[{"s": "(3-x) x x", "t": "text"}]',NULL,NULL,NULL),
(10422,43,408,'paragraph',NULL,'K c = [PCl 3 ][Cl 2 ]/[PCl 5 ]','[{"s": "K", "t": "text"}, {"s": "c", "t": "text"}, {"s": "= [PCl", "t": "text"}, {"s": "3", "t": "text"}, {"s": "][Cl", "t": "text"}, {"s": "2", "t": "text"}, {"s": "]/[PCl", "t": "text"}, {"s": "5", "t": "text"}, {"s": "]", "t": "text"}]',NULL,NULL,NULL),
(10423,43,409,'paragraph',NULL,'1.8 = x 2 / (3 – x)','[{"s": "1.8 = x", "t": "text"}, {"s": "2", "t": "text"}, {"s": "/ (3 – x)", "t": "text"}]',NULL,NULL,NULL),
(10424,43,410,'paragraph',NULL,'x 2 + 1.8x – 5.4 = 0','[{"s": "x", "t": "text"}, {"s": "2", "t": "text"}, {"s": "+ 1.8x – 5.4 = 0", "t": "text"}]',NULL,NULL,NULL),
(10425,43,411,'paragraph',NULL,'x = [–1.8 ± √(1.8) 2 – 4(–5.4)]/2','[{"s": "x = [–1.8 ± √(1.8)", "t": "text"}, {"s": "2", "t": "text"}, {"s": "– 4(–5.4)]/2", "t": "text"}]',NULL,NULL,NULL),
(10426,43,412,'paragraph',NULL,'x = [–1.8 ± √3.24 + 21.6]/2','[{"s": "x = [–1.8 ± √3.24 + 21.6]/2", "t": "text"}]',NULL,NULL,NULL),
(10427,43,413,'paragraph',NULL,'x = [–1.8 ± 4.98]/2','[{"s": "x = [–1.8 ± 4.98]/2", "t": "text"}]',NULL,NULL,NULL),
(10428,43,414,'paragraph',NULL,'x = [–1.8 + 4.98]/2 = 1.59','[{"s": "x = [–1.8 + 4.98]/2 = 1.59", "t": "text"}]',NULL,NULL,NULL),
(12409,44,1179,'paragraph',NULL,'2','[{"s": "2", "t": "text"}]',NULL,NULL,NULL),
(12410,44,1180,'paragraph',NULL,'2','[{"s": "2", "t": "text"}]',NULL,NULL,NULL),
(10429,43,415,'paragraph',NULL,'[PCl 5 ] = 3.0 – x = 3 –1.59 = 1.41 M','[{"s": "[PCl", "t": "text"}, {"s": "5", "t": "text"}, {"s": "] = 3.0 – x = 3 –1.59 = 1.41 M", "t": "text"}]',NULL,NULL,NULL),
(10430,43,416,'paragraph',NULL,'[PCl 3 ] = [Cl 2 ] = x = 1.59 M','[{"s": "[PCl", "t": "text"}, {"s": "3", "t": "text"}, {"s": "] = [Cl", "t": "text"}, {"s": "2", "t": "text"}, {"s": "] = x = 1.59 M", "t": "text"}]',NULL,NULL,NULL),
(10431,43,417,'heading',3,'7.7 Relationship between Equilibrium Constant K, Reaction Quotient Q and Gibbs Energy G',NULL,NULL,NULL,NULL),
(10432,43,418,'paragraph',NULL,'The value of K c for a reaction does not depend on the rate of the reaction. However, as you have studied in Unit 6, it is directly related to the thermodynamics of the reaction and in particular, to the change in Gibbs energy, ∆ G . If,','[{"s": "The value of", "t": "text"}, {"s": "K", "t": "text"}, {"s": "c", "t": "text"}, {"s": "for a reaction does not depend on the rate of the reaction. However, as you have studied in Unit 6, it is directly related to the thermodynamics of the reaction and in particular, to the change in Gibbs energy, ∆", "t": "text"}, {"s": "G", "t": "text"}, {"s": ". If,", "t": "text"}]',NULL,NULL,NULL),
(10433,43,419,'paragraph',NULL,'• ∆ G is negative, then the reaction is spontaneous and proceeds in the forward direction.','[{"s": "• ∆", "t": "text"}, {"s": "G", "t": "text"}, {"s": "is negative, then the reaction is spontaneous and proceeds in the forward direction.", "t": "text"}]',NULL,NULL,NULL),
(10434,43,420,'paragraph',NULL,'• ∆ G is positive, then reaction is considered non-spontaneous. Instead, as reverse reaction would have a negative ∆ G , the products of the forward reaction shall be converted to the reactants.','[{"s": "• ∆", "t": "text"}, {"s": "G", "t": "text"}, {"s": "is positive, then reaction is considered non-spontaneous. Instead, as reverse reaction would have a negative ∆", "t": "text"}, {"s": "G", "t": "text"}, {"s": ", the products of the forward reaction shall be converted to the reactants.", "t": "text"}]',NULL,NULL,NULL),
(10435,43,421,'paragraph',NULL,'• ∆ G is 0, reaction has achieved equilibrium; at this point, there is no longer any free energy left to drive the reaction.','[{"s": "• ∆", "t": "text"}, {"s": "G", "t": "text"}, {"s": "is 0, reaction has achieved equilibrium; at this point, there is no longer any free energy left to drive the reaction.", "t": "text"}]',NULL,NULL,NULL),
(10436,43,422,'paragraph',NULL,'A mathematical expression of this thermodynamic view of equilibrium can be described by the following equation:','[{"s": "A mathematical expression of this thermodynamic view of equilibrium can be described by the following equation:", "t": "text"}]',NULL,NULL,NULL),
(10437,43,423,'paragraph',NULL,'∆ G = ∆ G⊖ + RT ln Q (7.21)','[{"s": "∆", "t": "text"}, {"s": "G", "t": "text"}, {"s": "= ∆", "t": "text"}, {"s": "G⊖", "t": "text"}, {"s": "+ RT ln", "t": "text"}, {"s": "Q", "t": "text"}, {"s": "(7.21)", "t": "text"}]',NULL,NULL,NULL),
(10438,43,424,'paragraph',NULL,'where, G⊖ is standard Gibbs energy.','[{"s": "where,", "t": "text"}, {"s": "G⊖", "t": "text"}, {"s": "is standard Gibbs energy.", "t": "text"}]',NULL,NULL,NULL),
(10439,43,425,'paragraph',NULL,'At equilibrium, when ∆ G = 0 and Q = K c , the equation (7.21) becomes,','[{"s": "At equilibrium, when ∆", "t": "text"}, {"s": "G", "t": "text"}, {"s": "= 0 and", "t": "text"}, {"s": "Q", "t": "text"}, {"s": "=", "t": "text"}, {"s": "K", "t": "text"}, {"s": "c", "t": "text"}, {"s": ", the equation (7.21) becomes,", "t": "text"}]',NULL,NULL,NULL),
(10440,43,426,'paragraph',NULL,'∆ G = ∆ G⊖ + R T ln K = 0','[{"s": "∆", "t": "text"}, {"s": "G", "t": "text"}, {"s": "= ∆", "t": "text"}, {"s": "G⊖", "t": "text"}, {"s": "+ R", "t": "text"}, {"s": "T", "t": "text"}, {"s": "ln", "t": "text"}, {"s": "K", "t": "text"}, {"s": "= 0", "t": "text"}]',NULL,NULL,NULL),
(10441,43,427,'paragraph',NULL,'∆ G⊖ = – R T ln K (7.22)','[{"s": "∆", "t": "text"}, {"s": "G⊖", "t": "text"}, {"s": "= – R", "t": "text"}, {"s": "T", "t": "text"}, {"s": "ln", "t": "text"}, {"s": "K", "t": "text"}, {"s": "(7.22)", "t": "text"}]',NULL,NULL,NULL),
(10442,43,428,'paragraph',NULL,'ln K = – ∆ G⊖ / R T','[{"s": "ln", "t": "text"}, {"s": "K", "t": "text"}, {"s": "= – ∆", "t": "text"}, {"s": "G⊖", "t": "text"}, {"s": "/ R", "t": "text"}, {"s": "T", "t": "text"}]',NULL,NULL,NULL),
(10443,43,429,'paragraph',NULL,'Taking antilog of both sides, we get,','[{"s": "Taking antilog of both sides, we get,", "t": "text"}]',NULL,NULL,NULL),
(10444,43,430,'paragraph',NULL,'K = e – ∆ G ⊖/RT (7.23)','[{"s": "K", "t": "text"}, {"s": "= e", "t": "text"}, {"s": "–", "t": "text"}, {"s": "∆", "t": "text"}, {"s": "G", "t": "text"}, {"s": "⊖/RT", "t": "text"}, {"s": "(7.23)", "t": "text"}]',NULL,NULL,NULL),
(10445,43,431,'paragraph',NULL,'Hence, using the equation (7.23), the reaction spontaneity can be interpreted in terms of the value of ∆ G⊖ .','[{"s": "Hence, using the equation (7.23), the reaction spontaneity can be interpreted in terms of the value of ∆", "t": "text"}, {"s": "G⊖", "t": "text"}, {"s": ".", "t": "text"}]',NULL,NULL,NULL),
(10446,43,432,'paragraph',NULL,'• If ∆ G⊖ < 0, then –∆ G⊖ /R T is positive, and e – ∆ G ⊖/RT >1, making K >1, which implies a spontaneous reaction or the reaction which proceeds in the forward direction to such an extent that the products are present predominantly.','[{"s": "• If ∆", "t": "text"}, {"s": "G⊖", "t": "text"}, {"s": "< 0, then –∆", "t": "text"}, {"s": "G⊖", "t": "text"}, {"s": "/R", "t": "text"}, {"s": "T", "t": "text"}, {"s": "is positive, and e", "t": "text"}, {"s": "–", "t": "text"}, {"s": "∆", "t": "text"}, {"s": "G", "t": "text"}, {"s": "⊖/RT", "t": "text"}, {"s": ">1, making", "t": "text"}, {"s": "K", "t": "text"}, {"s": ">1, which implies a spontaneous reaction or the reaction which proceeds in the forward direction to such an extent that the products are present predominantly.", "t": "text"}]',NULL,NULL,NULL),
(12411,44,1181,'paragraph',NULL,'—','[{"s": "—", "t": "text"}]',NULL,NULL,NULL),
(12412,44,1182,'paragraph',NULL,'2','[{"s": "2", "t": "text"}]',NULL,NULL,NULL),
(12413,44,1183,'paragraph',NULL,'C','[{"s": "C", "t": "text"}]',NULL,NULL,NULL),
(12414,44,1184,'paragraph',NULL,'H','[{"s": "H", "t": "text"}]',NULL,NULL,NULL),
(12415,44,1185,'paragraph',NULL,'2','[{"s": "2", "t": "text"}]',NULL,NULL,NULL),
(12416,44,1186,'paragraph',NULL,'2','[{"s": "2", "t": "text"}]',NULL,NULL,NULL),
(12417,44,1187,'paragraph',NULL,'—','[{"s": "—", "t": "text"}]',NULL,NULL,NULL),
(12418,44,1188,'paragraph',NULL,'1','[{"s": "1", "t": "text"}]',NULL,NULL,NULL),
(10447,43,433,'paragraph',NULL,'• If ∆ G⊖ > 0, then –∆ G⊖ /R T is negative, and e – ∆ G ⊖/RT < 1, that is , K < 1, which implies a non-spontaneous reaction or a reaction which proceeds in the forward direction to such a small degree that only a very minute quantity of product is formed.','[{"s": "• If ∆", "t": "text"}, {"s": "G⊖", "t": "text"}, {"s": "> 0, then –∆", "t": "text"}, {"s": "G⊖", "t": "text"}, {"s": "/R", "t": "text"}, {"s": "T", "t": "text"}, {"s": "is negative, and e", "t": "text"}, {"s": "–", "t": "text"}, {"s": "∆", "t": "text"}, {"s": "G", "t": "text"}, {"s": "⊖/RT", "t": "text"}, {"s": "< 1, that is ,", "t": "text"}, {"s": "K", "t": "text"}, {"s": "< 1, which implies a non-spontaneous reaction or a reaction which proceeds in the forward direction to such a small degree that only a very minute quantity of product is formed.", "t": "text"}]',NULL,NULL,NULL),
(10448,43,434,'paragraph',NULL,'Problem 7.10','[{"s": "Problem 7.10", "t": "text"}]',NULL,NULL,NULL),
(10449,43,435,'paragraph',NULL,'The value of ∆ G⊖ for the phosphorylation of glucose in glycolysis is 13.8 kJ/mol. Find the value of K c at 298 K.','[{"s": "The value of ∆", "t": "text"}, {"s": "G⊖", "t": "text"}, {"s": "for the phosphorylation of glucose in glycolysis is 13.8 kJ/mol. Find the value of", "t": "text"}, {"s": "K", "t": "text"}, {"s": "c", "t": "text"}, {"s": "at 298 K.", "t": "text"}]',NULL,NULL,NULL),
(10450,43,436,'paragraph',NULL,'Solution','[{"s": "Solution", "t": "text"}]',NULL,NULL,NULL),
(10451,43,437,'paragraph',NULL,'∆ G⊖ = 13.8 kJ/mol = 13.8 × 10 3 J/mol','[{"s": "∆", "t": "text"}, {"s": "G⊖", "t": "text"}, {"s": "= 13.8 kJ/mol = 13.8 × 10", "t": "text"}, {"s": "3", "t": "text"}, {"s": "J/mol", "t": "text"}]',NULL,NULL,NULL),
(10452,43,438,'paragraph',NULL,'Also, ∆ G⊖ = – RT ln K c','[{"s": "Also, ∆", "t": "text"}, {"s": "G⊖", "t": "text"}, {"s": "= – RT ln", "t": "text"}, {"s": "K", "t": "text"}, {"s": "c", "t": "text"}]',NULL,NULL,NULL),
(10453,43,439,'paragraph',NULL,'Hence, ln K c = –13.8 × 10 3 J/mol (8.314 J mol –1 K –1 × 298 K)','[{"s": "Hence, ln", "t": "text"}, {"s": "K", "t": "text"}, {"s": "c", "t": "text"}, {"s": "= –13.8 × 10", "t": "text"}, {"s": "3", "t": "text"}, {"s": "J/mol (8.314 J mol", "t": "text"}, {"s": "–1", "t": "text"}, {"s": "K", "t": "text"}, {"s": "–1", "t": "text"}, {"s": "× 298 K)", "t": "text"}]',NULL,NULL,NULL),
