(10654,43,640,'paragraph',NULL,'= 10 –14','[{"s": "= 10", "t": "text"}, {"s": "–14", "t": "text"}]',NULL,NULL,NULL),
(10655,43,641,'paragraph',NULL,'Let, x = [OH – ] = [H 3 O + ] from H 2 O. The H 3 O +','[{"s": "Let, x = [OH", "t": "text"}, {"s": "–", "t": "text"}, {"s": "] = [H", "t": "text"}, {"s": "3", "t": "text"}, {"s": "O", "t": "text"}, {"s": "+", "t": "text"}, {"s": "] from H", "t": "text"}, {"s": "2", "t": "text"}, {"s": "O. The H", "t": "text"}, {"s": "3", "t": "text"}, {"s": "O", "t": "text"}, {"s": "+", "t": "text"}, {"s": "", "t": "br"}]',NULL,NULL,NULL),
(12444,44,1214,'paragraph',NULL,'2','[{"s": "2", "t": "text"}]',NULL,NULL,NULL),
