(12446,44,1216,'paragraph',NULL,'b','[{"s": "b", "t": "text"}]',NULL,NULL,NULL),
(10656,43,642,'paragraph',NULL,'HCl(aq) + H 2 O(l) Equilibrium-image1.png H 3 O + (aq) + Cl – (aq),','[{"s": "HCl(aq) + H", "t": "text"}, {"s": "2", "t": "text"}, {"s": "O(l)", "t": "text"}, {"s": "Equilibrium-image1.png", "t": "img", "alt": ""}, {"s": "H", "t": "text"}, {"s": "3", "t": "text"}, {"s": "O", "t": "text"}, {"s": "+", "t": "text"}, {"s": "(aq) + Cl", "t": "text"}, {"s": "–", "t": "text"}, {"s": "(aq),", "t": "text"}]',NULL,NULL,NULL),
(10657,43,643,'paragraph',NULL,'and (ii) from ionization of H 2 O. In these very dilute solutions, both sources of H 3 O + must be considered:','[{"s": "and (ii) from ionization of H", "t": "text"}, {"s": "2", "t": "text"}, {"s": "O. In these very dilute solutions, both sources of H", "t": "text"}, {"s": "3", "t": "text"}, {"s": "O", "t": "text"}, {"s": "+", "t": "text"}, {"s": "must be considered:", "t": "text"}]',NULL,NULL,NULL),
(10658,43,644,'paragraph',NULL,'[H 3 O + ] = 10 –8 + x','[{"s": "[H", "t": "text"}, {"s": "3", "t": "text"}, {"s": "O", "t": "text"}, {"s": "+", "t": "text"}, {"s": "] = 10", "t": "text"}, {"s": "–8", "t": "text"}, {"s": "+ x", "t": "text"}]',NULL,NULL,NULL),
(10659,43,645,'paragraph',NULL,'K w = (10 –8 + x)(x) = 10 –14','[{"s": "K", "t": "text"}, {"s": "w", "t": "text"}, {"s": "= (10", "t": "text"}, {"s": "–8", "t": "text"}, {"s": "+ x)(x) = 10", "t": "text"}, {"s": "–14", "t": "text"}]',NULL,NULL,NULL),
(10660,43,646,'paragraph',NULL,'or x 2 + 10 –8 x – 10 –14 = 0','[{"s": "or x", "t": "text"}, {"s": "2", "t": "text"}, {"s": "+ 10", "t": "text"}, {"s": "–8", "t": "text"}, {"s": "x – 10", "t": "text"}, {"s": "–14", "t": "text"}, {"s": "= 0", "t": "text"}]',NULL,NULL,NULL),
(10661,43,647,'paragraph',NULL,'[OH – ] = x = 9.5 × 10 –8','[{"s": "[OH", "t": "text"}, {"s": "–", "t": "text"}, {"s": "] = x = 9.5 × 10", "t": "text"}, {"s": "–8", "t": "text"}]',NULL,NULL,NULL),
