(10675,43,661,'paragraph',NULL,'The pH scale for the hydrogen ion concentration has been so useful that besides p K w , it has been extended to other species and quantities. Thus, we have:','[{"s": "The pH scale for the hydrogen ion concentration has been so useful that besides p", "t": "text"}, {"s": "K", "t": "text"}, {"s": "w", "t": "text"}, {"s": ", it has been extended to other species and quantities. Thus, we have:", "t": "text"}]',NULL,NULL,NULL),
(10676,43,662,'paragraph',NULL,'p K a = –log ( K a ) (7.31)','[{"s": "p", "t": "text"}, {"s": "K", "t": "text"}, {"s": "a", "t": "text"}, {"s": "= –log (", "t": "text"}, {"s": "K", "t": "text"}, {"s": "a", "t": "text"}, {"s": ") (7.31)", "t": "text"}]',NULL,NULL,NULL),
