(10696,43,682,'paragraph',NULL,'2) H 2 O + H 2 O Equilibrium-image1.png H 3 O + + OH –','[{"s": "2) H", "t": "text"}, {"s": "2", "t": "text"}, {"s": "O + H", "t": "text"}, {"s": "2", "t": "text"}, {"s": "O", "t": "text"}, {"s": "Equilibrium-image1.png", "t": "img", "alt": ""}, {"s": "H", "t": "text"}, {"s": "3", "t": "text"}, {"s": "O", "t": "text"}, {"s": "+", "t": "text"}, {"s": "+ OH", "t": "text"}, {"s": "–", "t": "text"}]',NULL,NULL,NULL),
(10697,43,683,'paragraph',NULL,'K w = 1.0 × 10 –14','[{"s": "K", "t": "text"}, {"s": "w", "t": "text"}, {"s": "= 1.0 × 10", "t": "text"}, {"s": "–14", "t": "text"}]',NULL,NULL,NULL),
(10698,43,684,'paragraph',NULL,'As K a >> K w , [1] is the principle reaction.','[{"s": "As", "t": "text"}, {"s": "K", "t": "text"}, {"s": "a", "t": "text"}, {"s": ">>", "t": "text"}, {"s": "K", "t": "text"}, {"s": "w", "t": "text"}, {"s": ", [1] is the principle reaction.", "t": "text"}]',NULL,NULL,NULL),
(10699,43,685,'paragraph',NULL,'HF + H 2 O Equilibrium-image1.png H 3 O + + F –','[{"s": "HF + H", "t": "text"}, {"s": "2", "t": "text"}, {"s": "O", "t": "text"}, {"s": "Equilibrium-image1.png", "t": "img", "alt": ""}, {"s": "H", "t": "text"}, {"s": "3", "t": "text"}, {"s": "O", "t": "text"}, {"s": "+", "t": "text"}, {"s": "+ F", "t": "text"}, {"s": "–", "t": "text"}]',NULL,NULL,NULL),
