(10702,43,688,'paragraph',NULL,'0.02 0 0','[{"s": "0.02 0 0", "t": "text"}]',NULL,NULL,NULL),
(10703,43,689,'paragraph',NULL,'Change (M)','[{"s": "Change (M)", "t": "text"}]',NULL,NULL,NULL),
(10704,43,690,'paragraph',NULL,'–0.02α +0.02α +0.02α','[{"s": "–0.02α +0.02α +0.02α", "t": "text"}]',NULL,NULL,NULL),
(10705,43,691,'paragraph',NULL,'Equilibrium','[{"s": "Equilibrium", "t": "text"}]',NULL,NULL,NULL),
(10706,43,692,'paragraph',NULL,'concentration (M)','[{"s": "concentration (M)", "t": "text"}]',NULL,NULL,NULL),
(10707,43,693,'paragraph',NULL,'0.02 – 0.02 α 0.02 α 0.02α','[{"s": "0.02 – 0.02 α 0.02 α 0.02α", "t": "text"}]',NULL,NULL,NULL),
(10708,43,694,'paragraph',NULL,'Substituting equilibrium concentrations in the equilibrium reaction for principal reaction gives:','[{"s": "Substituting equilibrium concentrations in the equilibrium reaction for principal reaction gives:", "t": "text"}]',NULL,NULL,NULL),
(10709,43,695,'paragraph',NULL,'K a = (0.02α) 2 / (0.02 – 0.02α)','[{"s": "K", "t": "text"}, {"s": "a", "t": "text"}, {"s": "= (0.02α)", "t": "text"}, {"s": "2", "t": "text"}, {"s": "/ (0.02 – 0.02α)", "t": "text"}]',NULL,NULL,NULL),
(10710,43,696,'paragraph',NULL,'= 0.02 α 2 / (1 –α) = 3.2 × 10 –4','[{"s": "= 0.02 α", "t": "text"}, {"s": "2", "t": "text"}, {"s": "/ (1 –α) = 3.2 × 10", "t": "text"}, {"s": "–4", "t": "text"}]',NULL,NULL,NULL),
(10711,43,697,'paragraph',NULL,'We obtain the following quadratic equation:','[{"s": "We obtain the following quadratic equation:", "t": "text"}]',NULL,NULL,NULL),
(10712,43,698,'paragraph',NULL,'α 2 + 1.6 × 10 –2 α – 1.6 × 10 –2 = 0','[{"s": "α", "t": "text"}, {"s": "2", "t": "text"}, {"s": "+ 1.6 × 10", "t": "text"}, {"s": "–2", "t": "text"}, {"s": "α – 1.6 × 10", "t": "text"}, {"s": "–2", "t": "text"}, {"s": "= 0", "t": "text"}]',NULL,NULL,NULL),
(10713,43,699,'paragraph',NULL,'The quadratic equation in α can be solved and the two values of the roots are:','[{"s": "The quadratic equation in α can be solved and the two values of the roots are:", "t": "text"}]',NULL,NULL,NULL),
(10714,43,700,'paragraph',NULL,'α = + 0.12 and – 0.12','[{"s": "α = + 0.12 and – 0.12", "t": "text"}]',NULL,NULL,NULL),
(10715,43,701,'paragraph',NULL,'The negative root is not acceptable and hence,','[{"s": "The negative root is not acceptable and hence,", "t": "text"}]',NULL,NULL,NULL),
(10716,43,702,'paragraph',NULL,'α = 0.12','[{"s": "α = 0.12", "t": "text"}]',NULL,NULL,NULL),
(10717,43,703,'paragraph',NULL,'This means that the degree of ionization, α = 0.12, then equilibrium concentrations of other species viz., HF, F – and H 3 O + are given by:','[{"s": "This means that the degree of ionization, α = 0.12, then equilibrium concentrations of other species viz., HF, F", "t": "text"}, {"s": "–", "t": "text"}, {"s": "and H", "t": "text"}, {"s": "3", "t": "text"}, {"s": "O", "t": "text"}, {"s": "+", "t": "text"}, {"s": "are given by:", "t": "text"}]',NULL,NULL,NULL),
(10718,43,704,'paragraph',NULL,'[H 3 O + ] = [F – ] = cα = 0.02 × 0.12','[{"s": "[H", "t": "text"}, {"s": "3", "t": "text"}, {"s": "O", "t": "text"}, {"s": "+", "t": "text"}, {"s": "] = [F", "t": "text"}, {"s": "–", "t": "text"}, {"s": "] = cα = 0.02 × 0.12", "t": "text"}]',NULL,NULL,NULL),
(10719,43,705,'paragraph',NULL,'= 2.4 × 10 –3 M','[{"s": "= 2.4 × 10", "t": "text"}, {"s": "–3", "t": "text"}, {"s": "M", "t": "text"}]',NULL,NULL,NULL),
(10720,43,706,'paragraph',NULL,'[HF] = c(1 – α) = 0.02 (1 – 0.12)','[{"s": "[HF] = c(1 – α) = 0.02 (1 – 0.12)", "t": "text"}]',NULL,NULL,NULL),
(10721,43,707,'paragraph',NULL,'= 17.6 × 10 -3 M','[{"s": "= 17.6 × 10", "t": "text"}, {"s": "-3", "t": "text"}, {"s": "M", "t": "text"}]',NULL,NULL,NULL),
(10722,43,708,'paragraph',NULL,'pH = – log[H + ] = –log(2.4 × 10 –3 ) = 2.62','[{"s": "pH = – log[H", "t": "text"}, {"s": "+", "t": "text"}, {"s": "] = –log(2.4 × 10", "t": "text"}, {"s": "–3", "t": "text"}, {"s": ") = 2.62", "t": "text"}]',NULL,NULL,NULL),
(10723,43,709,'paragraph',NULL,'Problem 7.19','[{"s": "Problem 7.19", "t": "text"}]',NULL,NULL,NULL),
(10724,43,710,'paragraph',NULL,'The pH of 0.1M monobasic acid is 4.50. Calculate the concentration of species H + , A – and HA at equilibrium. Also, determine the value of K a and p K a of the monobasic acid.','[{"s": "The pH of 0.1M monobasic acid is 4.50. Calculate the concentration of species H", "t": "text"}, {"s": "+", "t": "text"}, {"s": ", A", "t": "text"}, {"s": "–", "t": "text"}, {"s": "and HA at equilibrium. Also, determine the value of", "t": "text"}, {"s": "K", "t": "text"}, {"s": "a", "t": "text"}, {"s": "and p", "t": "text"}, {"s": "K", "t": "text"}, {"s": "a", "t": "text"}, {"s": "of the monobasic acid.", "t": "text"}]',NULL,NULL,NULL),
(10725,43,711,'paragraph',NULL,'Solution','[{"s": "Solution", "t": "text"}]',NULL,NULL,NULL),
(10726,43,712,'paragraph',NULL,'pH = – log [H + ]','[{"s": "pH = – log [H", "t": "text"}, {"s": "+", "t": "text"}, {"s": "]", "t": "text"}]',NULL,NULL,NULL),
(10727,43,713,'paragraph',NULL,'Therefore, [H + ] = 10 –pH = 10 –4.50','[{"s": "Therefore, [H", "t": "text"}, {"s": "+", "t": "text"}, {"s": "] = 10", "t": "text"}, {"s": "–pH", "t": "text"}, {"s": "= 10", "t": "text"}, {"s": "–4.50", "t": "text"}]',NULL,NULL,NULL),
(10728,43,714,'paragraph',NULL,'= 3.16 × 10 –5','[{"s": "= 3.16 × 10", "t": "text"}, {"s": "–5", "t": "text"}]',NULL,NULL,NULL),
(10729,43,715,'paragraph',NULL,'[H + ] = [A – ] = 3.16 × 10 –5','[{"s": "[H", "t": "text"}, {"s": "+", "t": "text"}, {"s": "] = [A", "t": "text"}, {"s": "–", "t": "text"}, {"s": "] = 3.16 × 10", "t": "text"}, {"s": "–5", "t": "text"}]',NULL,NULL,NULL),
(10730,43,716,'paragraph',NULL,'Thus, K a = [H + ][A - ] / [HA]','[{"s": "Thus,", "t": "text"}, {"s": "K", "t": "text"}, {"s": "a", "t": "text"}, {"s": "= [H", "t": "text"}, {"s": "+", "t": "text"}, {"s": "][A", "t": "text"}, {"s": "-", "t": "text"}, {"s": "] / [HA]", "t": "text"}]',NULL,NULL,NULL),
(10731,43,717,'paragraph',NULL,'[HA] eqlbm = 0.1 – (3.16 × 10 -5 ) Ä 0.1','[{"s": "[HA]", "t": "text"}, {"s": "eqlbm", "t": "text"}, {"s": "= 0.1 – (3.16 × 10", "t": "text"}, {"s": "-5", "t": "text"}, {"s": ") Ä 0.1", "t": "text"}]',NULL,NULL,NULL),
