(10751,43,737,'paragraph',NULL,'As x << 0.08, therefore 0.08 – x Ä 0.08','[{"s": "As x << 0.08, therefore 0.08 – x Ä 0.08", "t": "text"}]',NULL,NULL,NULL),
(10752,43,738,'paragraph',NULL,'x 2 / 0.08 = 2.5 × 10 –5','[{"s": "x", "t": "text"}, {"s": "2", "t": "text"}, {"s": "/ 0.08 = 2.5 × 10", "t": "text"}, {"s": "–5", "t": "text"}]',NULL,NULL,NULL),
(10753,43,739,'paragraph',NULL,'x 2 = 2.0 × 10 –6 , thus, x = 1.41 × 10 –3 [H + ] = 1.41 × 10 –3 M.','[{"s": "x", "t": "text"}, {"s": "2", "t": "text"}, {"s": "= 2.0 × 10", "t": "text"}, {"s": "–6", "t": "text"}, {"s": ", thus, x = 1.41 × 10", "t": "text"}, {"s": "–3", "t": "text"}, {"s": "[H", "t": "text"}, {"s": "+", "t": "text"}, {"s": "] = 1.41 × 10", "t": "text"}, {"s": "–3", "t": "text"}, {"s": "M.", "t": "text"}]',NULL,NULL,NULL),
(10754,43,740,'paragraph',NULL,'Therefore,','[{"s": "Therefore,", "t": "text"}]',NULL,NULL,NULL),
(10755,43,741,'paragraph',NULL,'Percent dissociation','[{"s": "Percent dissociation", "t": "text"}]',NULL,NULL,NULL),
(10756,43,742,'paragraph',NULL,'= {[HOCl] dissociated / [HOCl] initial }× 100','[{"s": "= {[HOCl]", "t": "text"}, {"s": "dissociated", "t": "text"}, {"s": "/ [HOCl]", "t": "text"}, {"s": "initial", "t": "text"}, {"s": "}× 100", "t": "text"}]',NULL,NULL,NULL),
(10757,43,743,'paragraph',NULL,'= 1.41 × 10 –3 × 10 2 / 0.08 = 1.76 %.','[{"s": "= 1.41 × 10", "t": "text"}, {"s": "–3", "t": "text"}, {"s": "× 10", "t": "text"}, {"s": "2", "t": "text"}, {"s": "/ 0.08 = 1.76 %.", "t": "text"}]',NULL,NULL,NULL),
(10758,43,744,'paragraph',NULL,'pH = –log(1.41 × 10 –3 ) = 2.85.','[{"s": "pH = –log(1.41 × 10", "t": "text"}, {"s": "–3", "t": "text"}, {"s": ") = 2.85.", "t": "text"}]',NULL,NULL,NULL),
(10759,43,745,'heading',4,'7.11.4 Ionization of Weak Bases',NULL,NULL,NULL,NULL),
