(10811,43,797,'paragraph',NULL,'= (5.6x10 –10 ) × (1.8 × 10 –5 ) = 1.0 × 10 –14 M','[{"s": "= (5.6x10", "t": "text"}, {"s": "–10", "t": "text"}, {"s": ") × (1.8 × 10", "t": "text"}, {"s": "–5", "t": "text"}, {"s": ") = 1.0 × 10", "t": "text"}, {"s": "–14", "t": "text"}, {"s": "M", "t": "text"}]',NULL,NULL,NULL),
(10812,43,798,'paragraph',NULL,'This can be extended to make a generalisation. The equilibrium constant for a net reaction obtained after adding two (or more) reactions equals the product of the equilibrium constants for individual reactions:','[{"s": "This can be extended to make a generalisation.", "t": "text"}, {"s": "The", "t": "hl"}, {"s": "equilibrium constant for a net reaction obtained after adding two (or more) reactions equals the product of the equilibrium constants for individual reactions:", "t": "hl"}]','marked','["71128"]',NULL),
