(10835,43,821,'paragraph',NULL,'The value of α is small, therefore the quadratic equation can be simplified by neglecting α in comparison to 1 in the denominator on right hand side of the equation,','[{"s": "The value of α is small, therefore the quadratic equation can be simplified by neglecting α in comparison to 1 in the denominator on right hand side of the equation,", "t": "text"}]',NULL,NULL,NULL),
(10836,43,822,'paragraph',NULL,'Thus,','[{"s": "Thus,", "t": "text"}]',NULL,NULL,NULL),
(10837,43,823,'paragraph',NULL,'K b = c α 2 or α = √ (1.77 × 10 –5 / 0.05)','[{"s": "K", "t": "text"}, {"s": "b", "t": "text"}, {"s": "= c α", "t": "text"}, {"s": "2", "t": "text"}, {"s": "or α = √ (1.77 × 10", "t": "text"}, {"s": "–5", "t": "text"}, {"s": "/ 0.05)", "t": "text"}]',NULL,NULL,NULL),
