(10840,43,826,'paragraph',NULL,'[H + ] = K w / [OH – ] = 10 –14 / (9.4 × 10 –4 )','[{"s": "[H", "t": "text"}, {"s": "+", "t": "text"}, {"s": "] =", "t": "text"}, {"s": "K", "t": "text"}, {"s": "w", "t": "text"}, {"s": "/ [OH", "t": "text"}, {"s": "–", "t": "text"}, {"s": "] = 10", "t": "text"}, {"s": "–14", "t": "text"}, {"s": "/ (9.4 × 10", "t": "text"}, {"s": "–4", "t": "text"}, {"s": ")", "t": "text"}]',NULL,NULL,NULL),
