(10880,43,866,'paragraph',NULL,'K a = [H + ][Ac – ]/[H Ac] = {(0.05+x)(x)}/(0.05-x)','[{"s": "K", "t": "text"}, {"s": "a", "t": "text"}, {"s": "= [H", "t": "text"}, {"s": "+", "t": "text"}, {"s": "][Ac", "t": "text"}, {"s": "–", "t": "text"}, {"s": "]/[H Ac] = {(0.05+x)(x)}/(0.05-x)", "t": "text"}]',NULL,NULL,NULL),
(10881,43,867,'paragraph',NULL,'As K a is small for a very weak acid, x<<0.05.','[{"s": "As", "t": "text"}, {"s": "K", "t": "text"}, {"s": "a", "t": "text"}, {"s": "is small for a very weak acid, x<<0.05.", "t": "text"}]',NULL,NULL,NULL),
(10882,43,868,'paragraph',NULL,'Hence, (0.05 + x) ≈ (0.05 – x) ≈ 0.05','[{"s": "Hence, (0.05 + x) ≈ (0.05 – x) ≈ 0.05", "t": "text"}]',NULL,NULL,NULL),
