(10885,43,871,'paragraph',NULL,'= x(0.05) / (0.05) = x = [H + ] = 1.8 × 10 –5 M','[{"s": "= x(0.05) / (0.05) = x = [H", "t": "text"}, {"s": "+", "t": "text"}, {"s": "] = 1.8 × 10", "t": "text"}, {"s": "–5", "t": "text"}, {"s": "M", "t": "text"}]',NULL,NULL,NULL),
