(10887,43,873,'paragraph',NULL,'Problem 7.24','[{"s": "Problem 7.24", "t": "text"}]',NULL,NULL,NULL),
(10888,43,874,'paragraph',NULL,'Calculate the pH of a 0.10M ammonia solution. Calculate the pH after 50.0 mL of this solution is treated with 25.0 mL of 0.10M HCl. The dissociation constant of ammonia, K b = 1.77 × 10 -5','[{"s": "Calculate the pH of a 0.10M ammonia solution. Calculate the pH after 50.0 mL of this solution is treated with 25.0 mL of 0.10M HCl. The dissociation constant of ammonia,", "t": "text"}, {"s": "K", "t": "text"}, {"s": "b", "t": "text"}, {"s": "= 1.77 × 10", "t": "text"}, {"s": "-5", "t": "text"}]',NULL,NULL,NULL),
(10889,43,875,'paragraph',NULL,'Solution','[{"s": "Solution", "t": "text"}]',NULL,NULL,NULL),
