(10896,43,882,'paragraph',NULL,'Thus, x = 1.33 × 10 –3 = [OH – ]','[{"s": "Thus, x = 1.33 × 10", "t": "text"}, {"s": "–3", "t": "text"}, {"s": "= [OH", "t": "text"}, {"s": "–", "t": "text"}, {"s": "]", "t": "text"}]',NULL,NULL,NULL),
(10897,43,883,'paragraph',NULL,'Therefore,[H + ] = K w / [OH – ] = 10 –14 /','[{"s": "Therefore,[H", "t": "text"}, {"s": "+", "t": "text"}, {"s": "] =", "t": "text"}, {"s": "K", "t": "text"}, {"s": "w", "t": "text"}, {"s": "/ [OH", "t": "text"}, {"s": "–", "t": "text"}, {"s": "] = 10", "t": "text"}, {"s": "–14", "t": "text"}, {"s": "/", "t": "text"}]',NULL,NULL,NULL),
(10898,43,884,'paragraph',NULL,'(1.33 × 10 –3 ) = 7.51 × 10 –12','[{"s": "(1.33 × 10", "t": "text"}, {"s": "–3", "t": "text"}, {"s": ") = 7.51 × 10", "t": "text"}, {"s": "–12", "t": "text"}]',NULL,NULL,NULL),
(10899,43,885,'paragraph',NULL,'pH = –log(7.5 × 10 –12 ) = 11.12','[{"s": "pH = –log(7.5 × 10", "t": "text"}, {"s": "–12", "t": "text"}, {"s": ") = 11.12", "t": "text"}]',NULL,NULL,NULL),
(10900,43,886,'paragraph',NULL,'On addition of 25 mL of 0.1M HCl solution (i.e., 2.5 mmol of HCl) to 50 mL of 0.1M ammonia solution (i.e., 5 mmol of NH 3 ), 2.5 mmol of ammonia molecules are neutralized. The resulting 75 mL solution contains the remaining unneutralized 2.5 mmol of NH 3 molecules and 2.5 mmol of NH 4 + .','[{"s": "On addition of 25 mL of 0.1M HCl solution (i.e., 2.5 mmol of HCl) to 50 mL of 0.1M ammonia solution (i.e., 5 mmol of NH", "t": "text"}, {"s": "3", "t": "text"}, {"s": "), 2.5 mmol of ammonia molecules are neutralized. The resulting 75 mL solution contains the remaining unneutralized 2.5 mmol of NH", "t": "text"}, {"s": "3", "t": "text"}, {"s": "molecules and 2.5 mmol of NH", "t": "text"}, {"s": "4", "t": "text"}, {"s": "+", "t": "text"}, {"s": ".", "t": "text"}]',NULL,NULL,NULL),
(10901,43,887,'paragraph',NULL,'NH 3 + HCl → NH 4 + + Cl –','[{"s": "NH", "t": "text"}, {"s": "3", "t": "text"}, {"s": "+ HCl → NH", "t": "text"}, {"s": "4", "t": "text"}, {"s": "+", "t": "text"}, {"s": "+ Cl", "t": "text"}, {"s": "–", "t": "text"}]',NULL,NULL,NULL),
(10902,43,888,'paragraph',NULL,'2.5 2.5 0 0','[{"s": "2.5 2.5 0 0", "t": "text"}]',NULL,NULL,NULL),
