(10939,43,925,'paragraph',NULL,'H 2 O Equilibrium-image1.png H + + OH –','[{"s": "H", "t": "text"}, {"s": "2", "t": "text"}, {"s": "O", "t": "text"}, {"s": "Equilibrium-image1.png", "t": "img", "alt": ""}, {"s": "H", "t": "text"}, {"s": "+", "t": "text"}, {"s": "+ OH", "t": "text"}, {"s": "–", "t": "text"}]',NULL,NULL,NULL),
(10940,43,926,'paragraph',NULL,'Without going into detailed calculation, it can be said that degree of hydrolysis is independent of concentration of solution, and pH of such solutions is determined by their p K values:','[{"s": "Without going into detailed calculation, it can be said that degree of hydrolysis is independent of concentration of solution, and pH of such solutions is determined by their p", "t": "text"}, {"s": "K", "t": "text"}, {"s": "values:", "t": "text"}]',NULL,NULL,NULL),
(10941,43,927,'paragraph',NULL,'pH = 7 + ½ (p K a – p K b ) (7.38)','[{"s": "pH = 7 + ½ (p", "t": "text"}, {"s": "K", "t": "text"}, {"s": "a", "t": "text"}, {"s": "– p", "t": "text"}, {"s": "K", "t": "text"}, {"s": "b", "t": "text"}, {"s": ") (7.38)", "t": "text"}]',NULL,NULL,NULL),
(10942,43,928,'paragraph',NULL,'The pH of solution can be greater than 7, if the difference is positive and it will be less than 7, if the difference is negative.','[{"s": "The pH of solution can be greater than 7, if the difference is positive and it will be less than 7, if the difference is negative.", "t": "text"}]',NULL,NULL,NULL),
(10943,43,929,'paragraph',NULL,'Problem 7.25','[{"s": "Problem 7.25", "t": "text"}]',NULL,NULL,NULL),
(10944,43,930,'paragraph',NULL,'The p K a of acetic acid and p K b of ammonium hydroxide are 4.76 and 4.75 respectively. Calculate the pH of ammonium acetate solution.','[{"s": "The p", "t": "text"}, {"s": "K", "t": "text"}, {"s": "a", "t": "text"}, {"s": "of acetic acid and p", "t": "text"}, {"s": "K", "t": "text"}, {"s": "b", "t": "text"}, {"s": "of ammonium hydroxide are 4.76 and 4.75 respectively. Calculate the pH of ammonium acetate solution.", "t": "text"}]',NULL,NULL,NULL),
(10945,43,931,'paragraph',NULL,'Solution','[{"s": "Solution", "t": "text"}]',NULL,NULL,NULL),
(10946,43,932,'paragraph',NULL,'pH = 7 + ½ [p K a – p K b ]','[{"s": "pH = 7 + ½ [p", "t": "text"}, {"s": "K", "t": "text"}, {"s": "a", "t": "text"}, {"s": "– p", "t": "text"}, {"s": "K", "t": "text"}, {"s": "b", "t": "text"}, {"s": "]", "t": "text"}]',NULL,NULL,NULL),
(10947,43,933,'paragraph',NULL,'= 7 + ½ [4.76 – 4.75]','[{"s": "= 7 + ½ [4.76 – 4.75]", "t": "text"}]',NULL,NULL,NULL),
(10948,43,934,'paragraph',NULL,'= 7 + ½ [0.01] = 7 + 0.005 = 7.005','[{"s": "= 7 + ½ [0.01] = 7 + 0.005 = 7.005", "t": "text"}]',NULL,NULL,NULL),
